// Banque de questions — examen civique
// Construite à partir de la liste officielle des questions de connaissance publiée par le ministère de l'Intérieur
// (formation-civique.interieur.gouv.fr) + quelques mises en situation (s:1) sur le même modèle.
// Format : th = thème, q = question, a = bonne réponse, w = mauvaises réponses, e = explication, s = mise en situation
const THEMES = {
  valeurs: "Principes et valeurs de la République",
  institutions: "Système institutionnel et politique",
  droits: "Droits et devoirs",
  histoire: "Histoire, géographie et culture",
  societe: "Vivre dans la société française"
};
const QUESTIONS = [
// ===================== PRINCIPES ET VALEURS =====================
{th:"valeurs",q:"Parmi les propositions suivantes, laquelle constitue une participation citoyenne ?",a:"Voter aux élections",w:["Regarder le journal télévisé","Payer ses courses en espèces","Partir en vacances à l'étranger"],e:"Voter, s'engager dans une association ou être bénévole sont des formes de participation à la vie citoyenne."},
{th:"valeurs",q:"Que garantit la liberté d'expression ?",a:"Le droit d'exprimer librement ses opinions, dans les limites prévues par la loi",w:["Le droit de dire absolument tout, y compris insulter","Le droit de publier uniquement des opinions approuvées par l'État","Le droit de s'exprimer seulement pendant les élections"],e:"La liberté d'expression est garantie (DDHC, art. 11), mais l'injure, la diffamation ou l'incitation à la haine sont punies."},
{th:"valeurs",q:"À quoi sert un titre de séjour ?",a:"À prouver qu'un étranger a le droit de séjourner légalement en France",w:["À voter aux élections présidentielles","À devenir automatiquement français","À voyager sans passeport dans le monde entier"],e:"Le titre de séjour autorise un ressortissant étranger à résider en France pendant sa durée de validité."},
{th:"valeurs",q:"La liberté de circulation permet à toute personne de :",a:"Se déplacer librement sur le territoire",w:["Entrer dans n'importe quelle propriété privée","Conduire sans permis","Ne pas respecter le code de la route"],e:"Aller et venir librement est une liberté fondamentale, dans le respect de la loi."},
{th:"valeurs",q:"Complétez ces paroles de la Marseillaise : « Allons enfants de la Patrie, le jour de gloire est… »",a:"arrivé",w:["passé","venu","levé"],e:"« Allons enfants de la Patrie, le jour de gloire est arrivé ! » — début de l'hymne national."},
{th:"valeurs",q:"Complétez les paroles de la Marseillaise : « Aux armes, citoyens, formez… »",a:"vos bataillons",w:["vos régiments","vos armées","vos drapeaux"],e:"« Aux armes, citoyens, formez vos bataillons ! » — refrain de la Marseillaise."},
{th:"valeurs",q:"En application de la liberté individuelle, quelle proposition est correcte ? Une personne peut :",a:"Choisir librement la personne avec qui elle se marie",w:["Être mariée de force par sa famille","Être enfermée chez elle par son conjoint","Être obligée de suivre la religion de ses parents"],e:"La liberté individuelle protège les choix personnels : mariage, religion, déplacements…"},
{th:"valeurs",q:"Concernant la pratique de la religion, quelle proposition est correcte ?",a:"Chacun est libre de pratiquer sa religion dans le respect de l'ordre public",w:["La religion catholique est obligatoire","Il est interdit de pratiquer une religion en public","L'État choisit la religion de chaque citoyen"],e:"La liberté de culte est garantie (loi de 1905), dans le respect de l'ordre public."},
{th:"valeurs",q:"En tant que parent, peut-on refuser que son enfant participe aux cours de sport à l'école car ils sont mixtes ?",a:"Non, les cours sont obligatoires et la mixité est la règle",w:["Oui, si on le justifie par écrit","Oui, pour les filles uniquement","Oui, à partir du collège"],e:"Les enseignements (dont l'EPS) sont obligatoires ; on ne peut pas les refuser pour un motif religieux ou de mixité."},
{th:"valeurs",q:"Quelle est la devise de la France ?",a:"Liberté, Égalité, Fraternité",w:["Travail, Famille, Patrie","Unité, Progrès, Justice","Paix, Travail, Solidarité"],e:"La devise de la République est inscrite dans la Constitution (art. 2)."},
{th:"valeurs",q:"La répudiation de sa femme est :",a:"Interdite et sans valeur en France",w:["Autorisée si le mari le décide","Autorisée avec l'accord du maire","Autorisée si elle a eu lieu à l'étranger"],e:"En France, seul le divorce prononcé selon la loi met fin au mariage ; la répudiation est contraire à l'égalité femmes-hommes."},
{th:"valeurs",q:"Les impôts permettent de financer les dépenses publiques. Quelle proposition est correcte ?",a:"Chacun contribue selon ses moyens",w:["Seuls les étrangers paient des impôts","Tout le monde paie exactement le même montant","Les impôts sont facultatifs"],e:"La contribution commune « doit être également répartie entre tous les citoyens, en raison de leurs facultés » (DDHC, art. 13)."},
{th:"valeurs",q:"Peut-on brûler publiquement un drapeau français ?",a:"Non, l'outrage au drapeau est puni par la loi",w:["Oui, c'est la liberté d'expression sans limite","Oui, mais seulement le 14 juillet","Oui, si le drapeau nous appartient"],e:"L'outrage public au drapeau tricolore est une infraction sanctionnée par une amende."},
{th:"valeurs",q:"Que fait l'État pour lutter contre les discriminations ?",a:"Il les interdit par la loi et sanctionne leurs auteurs",w:["Il les autorise dans les entreprises privées","Il ne s'en occupe pas","Il les autorise si elles sont discrètes"],e:"Les discriminations (origine, sexe, religion, handicap…) sont punies ; le Défenseur des droits peut être saisi."},
{th:"valeurs",q:"Que représente Marianne ?",a:"La République française",w:["La première reine de France","La mère de Napoléon","La sainte patronne de Paris"],e:"Marianne est l'allégorie de la République ; son buste est présent dans les mairies."},
{th:"valeurs",q:"Qu'est-ce que la liberté d'association ?",a:"Le droit de créer une association ou d'y adhérer librement",w:["L'obligation d'adhérer à un syndicat","Le droit de s'associer pour commettre une infraction","Le droit réservé aux partis politiques"],e:"Liberté garantie par la loi du 1er juillet 1901."},
{th:"valeurs",q:"Qu'est-ce que la liberté ?",a:"Pouvoir faire tout ce qui ne nuit pas à autrui",w:["Pouvoir faire absolument tout ce qu'on veut","Ne jamais respecter la loi","Ne dépendre de personne financièrement"],e:"Définition de l'article 4 de la Déclaration des droits de l'homme et du citoyen de 1789."},
{th:"valeurs",q:"Qu'est-ce que la Marseillaise ?",a:"L'hymne national",w:["La devise de la République","Une fête nationale","Le drapeau de la ville de Marseille"],e:"Composée en 1792 par Rouget de Lisle, elle est l'hymne national (Constitution, art. 2)."},
{th:"valeurs",q:"Sur quel document peut-on voir Marianne ?",a:"Sur les timbres-poste et le logo des documents officiels",w:["Sur les billets en euros","Sur le permis de pêche uniquement","Sur aucun document"],e:"Marianne figure sur les timbres, les pièces françaises de centimes et le logo de la République."},
{th:"valeurs",q:"Un employeur refuse d'embaucher des femmes dans son entreprise. Que dit la loi ?",a:"C'est une discrimination interdite et punie",w:["C'est autorisé dans le secteur privé","C'est autorisé si l'entreprise est petite","C'est autorisé si le patron l'annonce"],e:"Refuser d'embaucher en raison du sexe est une discrimination sanctionnée pénalement."},
{th:"valeurs",q:"Une des valeurs de la devise républicaine est l'égalité. Qu'est-ce que cela signifie ?",a:"Tous les citoyens sont égaux devant la loi",w:["Tout le monde a le même salaire","Tout le monde doit avoir le même avis","Les hommes ont plus de droits que les femmes"],e:"Égalité devant la loi, sans distinction d'origine, de race ou de religion (Constitution, art. 1)."},
{th:"valeurs",q:"Quelle est la place de la langue française dans la République ?",a:"C'est la langue de la République",w:["Elle est facultative dans l'administration","Elle est à égalité avec l'anglais dans la Constitution","Elle n'est utilisée qu'à Paris"],e:"« La langue de la République est le français » (Constitution, art. 2)."},
{th:"valeurs",q:"Quels sont des symboles officiels de la République française ?",a:"Le drapeau tricolore, la Marseillaise, la devise et le 14 Juillet",w:["La tour Eiffel et la baguette","Le coq gaulois et le camembert","La croix et le croissant"],e:"Drapeau, hymne, devise, fête nationale et Marianne sont les symboles de la République."},
{th:"valeurs",q:"A-t-on le droit d'insulter publiquement quelqu'un parce qu'il est différent (handicap, apparence physique, sexe…) ?",a:"Non, c'est une injure discriminatoire punie par la loi",w:["Oui, c'est la liberté d'expression","Oui, si c'est sur Internet","Oui, si c'est pour plaisanter"],e:"L'injure à caractère discriminatoire est un délit."},
{th:"valeurs",q:"Le régime de la France est :",a:"Une République démocratique",w:["Une monarchie constitutionnelle","Un empire","Une dictature militaire"],e:"La France est une République indivisible, laïque, démocratique et sociale."},
{th:"valeurs",q:"Pourquoi le principe de laïcité doit-il être respecté à l'école ?",a:"Pour protéger la liberté de conscience des élèves",w:["Pour interdire aux élèves d'avoir une religion","Pour imposer une religion d'État","Pour supprimer les cours d'histoire des religions"],e:"L'école publique est neutre : elle protège les élèves de toute pression religieuse ou politique."},
{th:"valeurs",q:"En quelle année la loi de séparation des Églises et de l'État a-t-elle été votée ?",a:"1905",w:["1789","1848","1958"],e:"La loi du 9 décembre 1905 fonde la laïcité en France."},
{th:"valeurs",q:"Une personne a-t-elle le droit de ne pas croire en une religion ?",a:"Oui, la liberté de conscience le garantit",w:["Non, chacun doit avoir une religion","Seulement avec une autorisation","Seulement après 30 ans"],e:"On peut croire, ne pas croire ou changer de religion."},
{th:"valeurs",q:"Quel droit est garanti par la laïcité ?",a:"La liberté de croire ou de ne pas croire",w:["Le droit d'imposer sa religion aux autres","Le droit de ne pas respecter la loi pour raison religieuse","Le droit de prier pendant les heures de travail dans un service public"],e:"La laïcité garantit la liberté de conscience et l'égalité de tous, quelle que soit leur conviction."},
{th:"valeurs",q:"À l'école publique, qui peut porter des signes religieux très visibles ?",a:"Ni les élèves ni les enseignants",w:["Les élèves uniquement","Les enseignants uniquement","Tout le monde"],e:"La loi de 2004 interdit les signes ostensibles aux élèves ; les enseignants, agents publics, sont soumis à la neutralité."},
{th:"valeurs",q:"Selon le principe de laïcité, que signifie la neutralité de l'État ?",a:"L'État ne favorise ni ne défavorise aucune religion",w:["L'État finance toutes les religions","L'État interdit les religions","L'État soutient la religion majoritaire"],e:"L'État et les services publics sont neutres vis-à-vis de toutes les croyances."},
{th:"valeurs",q:"Que peut faire un usager du service public dans une mairie ?",a:"Porter un signe religieux, s'il respecte l'ordre public et le fonctionnement du service",w:["Exiger d'être reçu par un agent du même sexe","Refuser de montrer son visage pour une vérification d'identité","Faire du prosélytisme auprès des agents"],e:"La neutralité s'impose aux agents, pas aux usagers — mais ceux-ci doivent respecter les règles du service."},
{th:"valeurs",q:"Qui doit respecter le principe de neutralité religieuse dans une préfecture ?",a:"Les agents qui y travaillent",w:["Les usagers qui viennent faire une démarche","Uniquement le préfet","Personne"],e:"Les agents publics sont tenus à la neutralité dans l'exercice de leurs fonctions."},
{th:"valeurs",q:"La laïcité impose-t-elle aux agents publics d'être neutres vis-à-vis des usagers ?",a:"Oui, toujours",w:["Non, jamais","Seulement le dimanche","Seulement s'ils travaillent dans une école"],e:"Un agent public ne peut pas manifester ses convictions religieuses dans son service."},
{th:"valeurs",q:"Que garantit le principe de laïcité ?",a:"La liberté de conscience et l'égalité de tous devant la loi, quelles que soient leurs croyances",w:["L'interdiction de toutes les religions","La supériorité d'une religion sur les autres","Le financement des lieux de culte par l'État"],e:"La République « respecte toutes les croyances » (Constitution, art. 1)."},
{th:"valeurs",q:"A-t-on le droit de changer de religion ?",a:"Oui",w:["Non","Seulement avec l'accord de sa famille","Seulement avec l'accord du maire"],e:"La liberté de conscience inclut le droit de changer de religion ou d'abandonner toute religion."},
{th:"valeurs",q:"Que représente la laïcité ?",a:"La séparation entre les religions et l'État",w:["La religion officielle de la France","L'interdiction de croire en Dieu","Une fête religieuse"],e:"Depuis 1905, la République ne reconnaît, ne salarie ni ne subventionne aucun culte."},
{th:"valeurs",q:"Qu'est-ce qui est interdit par la Charte de la laïcité à l'école ?",a:"Refuser un enseignement en invoquant sa religion",w:["Étudier l'histoire des religions","Avoir une religion","Parler de ses croyances en famille"],e:"Aucun élève ne peut contester le programme ou refuser un cours pour des raisons religieuses."},
{th:"valeurs",q:"Que dit l'article 1er de la Constitution française ?",a:"La France est une République indivisible, laïque, démocratique et sociale",w:["La France est un royaume chrétien","Le président a tous les pouvoirs","Paris est la capitale de l'Europe"],e:"Il affirme aussi l'égalité de tous devant la loi et le respect de toutes les croyances."},
{th:"valeurs",s:1,q:"Votre voisin vous dit qu'il ne veut pas que sa fille aille à l'école parce qu'elle est une fille. Que dit la loi ?",a:"L'instruction est obligatoire pour tous les enfants, filles et garçons",w:["C'est le choix du père","L'école est facultative pour les filles","Il suffit de prévenir la mairie"],e:"L'instruction est obligatoire de 3 à 16 ans, sans distinction de sexe."},
{th:"valeurs",s:1,q:"Une collègue porte un signe religieux dans une entreprise privée. Que prévoit la règle générale ?",a:"C'est permis, sauf si le règlement intérieur le restreint pour des raisons justifiées",w:["C'est toujours interdit comme dans la fonction publique","Il faut l'accord du maire","C'est interdit dans toutes les entreprises de plus de 10 salariés"],e:"La neutralité concerne les agents publics ; dans le privé, les restrictions doivent être justifiées et proportionnées."},

// ===================== INSTITUTIONS =====================
{th:"institutions",q:"Qu'est-ce que l'État de droit ?",a:"Un État où tout le monde, y compris les dirigeants, doit respecter la loi",w:["Un État où le président fait la loi seul","Un État sans police","Un État où seuls les citoyens doivent respecter la loi"],e:"Dans un État de droit, les pouvoirs publics sont soumis au droit et contrôlés par des juges indépendants."},
{th:"institutions",q:"Le président de la République a commis un crime. Quelle proposition est correcte ?",a:"Il ne peut pas être poursuivi pendant son mandat, mais pourra l'être après",w:["Il ne pourra jamais être poursuivi","Il est jugé immédiatement par le Premier ministre","Il est jugé par l'Église"],e:"Le président bénéficie d'une immunité temporaire (art. 67) ; il peut aussi être destitué par le Parlement en cas de manquement grave (art. 68)."},
{th:"institutions",q:"La loi est l'expression de :",a:"La volonté générale",w:["La volonté du président","La volonté des juges","La volonté des religions"],e:"Article 6 de la Déclaration des droits de l'homme et du citoyen de 1789."},
{th:"institutions",q:"Quelle est la durée du mandat du conseil municipal et du maire ?",a:"6 ans",w:["4 ans","5 ans","7 ans"],e:"Les élections municipales ont lieu tous les 6 ans (prochaines en 2026, puis 2032)."},
{th:"institutions",q:"Que garantit l'État de droit ?",a:"La protection des droits et libertés de chacun par la loi et les juges",w:["Le pouvoir absolu du gouvernement","L'absence de tribunaux","L'impunité des élus"],e:"Il garantit notamment la séparation des pouvoirs et l'indépendance de la justice."},
{th:"institutions",q:"Une personne peut-elle voter à la place d'une autre ?",a:"Seulement avec une procuration",w:["Oui, librement","Oui, si c'est un membre de sa famille","Non, jamais"],e:"Le vote est personnel ; la procuration permet à un électeur de confiance de voter pour soi."},
{th:"institutions",q:"Est-ce que le vote est obligatoire ?",a:"Non, c'est un droit et un devoir civique, mais il n'est pas obligatoire",w:["Oui, sous peine de prison","Oui, sous peine de perdre sa nationalité","Oui, seulement pour l'élection présidentielle"],e:"En France, l'abstention n'est pas sanctionnée (sauf pour les grands électeurs aux sénatoriales)."},
{th:"institutions",q:"À la fin de son mandat, le président de la République peut-il décider de rester au pouvoir ?",a:"Non, il doit respecter la durée de son mandat",w:["Oui, s'il le souhaite","Oui, avec l'accord de l'armée","Oui, s'il est populaire"],e:"Mandat de 5 ans, renouvelable une seule fois consécutivement."},
{th:"institutions",q:"Qui dirige l'action du Gouvernement ?",a:"Le Premier ministre",w:["Le président du Sénat","Le maire de Paris","Le président du Conseil constitutionnel"],e:"« Le Premier ministre dirige l'action du Gouvernement » (Constitution, art. 21)."},
{th:"institutions",q:"Qui nomme le Premier ministre ?",a:"Le président de la République",w:["Les députés par un vote","Le Sénat","Le peuple au suffrage direct"],e:"Article 8 de la Constitution."},
{th:"institutions",q:"Quelle est l'organisation administrative de la France ?",a:"Des communes, des départements et des régions",w:["Des provinces et des comtés","Des États fédérés","Des cantons uniquement"],e:"Ce sont les trois niveaux de collectivités territoriales (organisation décentralisée)."},
{th:"institutions",q:"Qu'est-ce que le pouvoir législatif ? Le pouvoir :",a:"De voter les lois",w:["D'appliquer les lois","De juger","De commander l'armée"],e:"Il appartient au Parlement (Assemblée nationale et Sénat)."},
{th:"institutions",q:"Pourquoi séparer les trois pouvoirs dans une démocratie ?",a:"Pour éviter qu'une seule personne ou institution concentre tous les pouvoirs",w:["Pour ralentir les décisions","Pour donner plus de pouvoir au président","Pour supprimer les élections"],e:"Principe théorisé par Montesquieu et affirmé à l'article 16 de la DDHC."},
{th:"institutions",q:"Qui sanctionne l'auteur d'un vol ?",a:"La justice (les juges)",w:["La victime elle-même","Le maire","Les voisins"],e:"Nul ne peut se faire justice soi-même ; seuls les tribunaux prononcent les peines."},
{th:"institutions",q:"Quel est le rôle du gouvernement ?",a:"Déterminer et conduire la politique de la Nation",w:["Voter les lois","Juger les citoyens","Élire le président"],e:"Article 20 de la Constitution ; il applique les lois et dispose de l'administration."},
{th:"institutions",q:"Que se passe-t-il si un ministre ne respecte pas la loi ?",a:"Il peut être poursuivi et jugé comme tout le monde",w:["Rien, il est au-dessus des lois","Il est promu","Seul le président peut le punir"],e:"Pour les actes commis dans ses fonctions, il est jugé par la Cour de justice de la République."},
{th:"institutions",q:"Combien de députés composent l'Assemblée nationale ?",a:"577",w:["348","100","925"],e:"577 députés, élus pour 5 ans au suffrage universel direct."},
{th:"institutions",q:"Qui peut voter aux élections en France ?",a:"Les citoyens français majeurs inscrits sur les listes électorales",w:["Toute personne vivant en France","Les personnes de plus de 16 ans","Seulement les propriétaires"],e:"Les citoyens européens résidant en France peuvent en plus voter aux municipales et aux européennes."},
{th:"institutions",q:"Pour combien de temps sont élus les sénateurs ?",a:"6 ans",w:["5 ans","7 ans","9 ans"],e:"348 sénateurs, élus au suffrage indirect, renouvelés par moitié tous les 3 ans."},
{th:"institutions",q:"La séparation des pouvoirs est un principe fondamental. Quels sont les trois pouvoirs concernés ?",a:"Législatif, exécutif et judiciaire",w:["Militaire, religieux et civil","Municipal, régional et national","Médiatique, économique et politique"],e:"Faire la loi, l'appliquer, juger."},
{th:"institutions",q:"Est-ce que le président de la République a tous les pouvoirs ?",a:"Non, ses pouvoirs sont limités par la Constitution",w:["Oui, il décide de tout","Oui, pendant les vacances parlementaires","Oui, s'il est réélu"],e:"Il partage le pouvoir exécutif avec le gouvernement, et le Parlement et les juges le contrôlent."},
{th:"institutions",q:"Qui est le préfet ?",a:"Le représentant de l'État dans le département ou la région",w:["Le chef de la police municipale","Un élu de la commune","Le président du conseil départemental"],e:"Nommé par le président de la République, il veille à l'application des lois et à l'ordre public."},
{th:"institutions",q:"Quelle condition est nécessaire pour voter aux élections ?",a:"Être inscrit sur les listes électorales",w:["Être propriétaire","Avoir un emploi","Être marié"],e:"Il faut aussi être majeur et jouir de ses droits civiques (et être français, sauf municipales/européennes pour les citoyens UE)."},
{th:"institutions",q:"Qui dirige la commune ?",a:"Le maire, avec le conseil municipal",w:["Le préfet","Le curé","Le député"],e:"Le maire est élu par le conseil municipal, lui-même élu par les habitants."},
{th:"institutions",q:"Quel est le régime politique de la France aujourd'hui ?",a:"La Ve République, une démocratie",w:["La IIIe République","Une monarchie","L'Empire"],e:"La Constitution de la Ve République date du 4 octobre 1958."},
{th:"institutions",q:"Qu'est-ce que l'Hôtel de Matignon ?",a:"La résidence et le lieu de travail du Premier ministre",w:["La résidence du président de la République","Le siège du Sénat","Un musée parisien"],e:"Le président réside au palais de l'Élysée, le Sénat siège au palais du Luxembourg."},
{th:"institutions",q:"Le Parlement est composé :",a:"De l'Assemblée nationale et du Sénat",w:["Du président et du gouvernement","Des maires et des préfets","Du Conseil constitutionnel"],e:"Les deux chambres votent la loi et contrôlent le gouvernement."},
{th:"institutions",q:"Quel est le rôle du président de la République ?",a:"Veiller au respect de la Constitution et garantir l'indépendance nationale",w:["Voter les lois à la place des députés","Juger les crimes","Diriger les communes"],e:"Il est aussi chef des armées et nomme le Premier ministre (art. 5, 8, 15)."},
{th:"institutions",q:"Quel est le rôle du Premier ministre ?",a:"Diriger l'action du gouvernement",w:["Commander l'armée seul","Présider le Sénat","Élire le président"],e:"Il est responsable devant l'Assemblée nationale."},
{th:"institutions",q:"Qui est le chef du Gouvernement ?",a:"Le Premier ministre",w:["Le président de l'Assemblée nationale","Le ministre de l'Intérieur","Le maire de Paris"],e:"Le président de la République préside le Conseil des ministres, mais le chef du Gouvernement est le Premier ministre."},
{th:"institutions",q:"Combien y a-t-il de régions en France ?",a:"18 (13 en métropole et 5 en outre-mer)",w:["22","13 au total","101"],e:"Depuis la réforme de 2016 ; il y a 101 départements."},
{th:"institutions",q:"Quel est le rôle du Défenseur des droits ?",a:"Défendre les droits des personnes face aux administrations et lutter contre les discriminations",w:["Défendre les accusés au tribunal","Défendre le territoire militairement","Voter les lois"],e:"Autorité indépendante saisissable gratuitement."},
{th:"institutions",q:"Depuis quand l'euro est-il la monnaie unique utilisée par les Français au quotidien ?",a:"2002",w:["1992","1981","2010"],e:"L'euro existe depuis 1999 pour les banques ; les pièces et billets circulent depuis le 1er janvier 2002."},
{th:"institutions",q:"Quel est le rôle principal du département ?",a:"L'action sociale et la solidarité (RSA, aide aux personnes âgées et handicapées)",w:["Battre monnaie","Voter les lois","Gérer l'armée"],e:"Il gère aussi les collèges et une partie des routes."},
{th:"institutions",q:"Quel est le rôle principal des communes ?",a:"Gérer les services de proximité : état civil, écoles primaires, urbanisme",w:["Gérer les universités","Fixer les impôts nationaux","Gérer les ambassades"],e:"La mairie enregistre naissances, mariages et décès."},
{th:"institutions",q:"Combien de communes environ existe-t-il en France ?",a:"Environ 35 000",w:["Environ 3 500","Environ 350","Environ 350 000"],e:"La France compte un peu moins de 35 000 communes, un record en Europe."},
{th:"institutions",q:"Quel traité concerne la construction de l'Union européenne ?",a:"Le traité de Maastricht",w:["Le traité de Versailles","Le traité de Westphalie","Le traité de Tordesillas"],e:"Signé en 1992, il crée l'Union européenne ; le traité de Rome (1957) avait créé la CEE."},
{th:"institutions",q:"Quel État a quitté l'Union européenne en 2020 ?",a:"Le Royaume-Uni",w:["La Suisse","La Norvège","La Grèce"],e:"C'est le Brexit, effectif le 31 janvier 2020."},
{th:"institutions",q:"Quelle est la devise de l'Union européenne ?",a:"« Unie dans la diversité »",w:["« Liberté, Égalité, Fraternité »","« L'union fait la force »","« Paix et prospérité »"],e:"Adoptée en 2000."},
{th:"institutions",q:"Quel est l'hymne de l'Union européenne ?",a:"L'Ode à la joie de Beethoven",w:["La Marseillaise","Le Boléro de Ravel","Les Quatre Saisons de Vivaldi"],e:"Extrait de la 9e symphonie de Beethoven."},
{th:"institutions",q:"De quoi est composé le drapeau européen ?",a:"De 12 étoiles dorées en cercle",w:["De 27 étoiles, une par pays","D'un aigle doré","De bandes bleues et jaunes"],e:"Le nombre 12 symbolise la perfection et l'unité, pas le nombre de pays."},
{th:"institutions",q:"De quelle couleur est le drapeau européen ?",a:"Bleu avec des étoiles jaunes (dorées)",w:["Rouge avec des étoiles blanches","Vert et blanc","Bleu, blanc et rouge"],e:"Un cercle de 12 étoiles dorées sur fond bleu."},
{th:"institutions",q:"En quelle année le traité de Maastricht, qui marque la fondation de l'Union européenne, a-t-il été signé ?",a:"1992",w:["1957","1945","2002"],e:"Signé le 7 février 1992."},
{th:"institutions",q:"Où est le siège du Parlement européen ?",a:"À Strasbourg",w:["À Paris","À Berlin","À Genève"],e:"Certaines sessions et commissions se tiennent aussi à Bruxelles."},
{th:"institutions",q:"Où est le siège de la Commission européenne ?",a:"À Bruxelles",w:["À Strasbourg","À Luxembourg","À Rome"],e:"Bruxelles accueille la Commission et le Conseil de l'UE."},
{th:"institutions",q:"Quel État n'est pas membre de l'Union européenne ?",a:"La Suisse",w:["L'Espagne","La Belgique","La Pologne"],e:"La Suisse et la Norvège ne sont pas membres de l'UE (le Royaume-Uni l'a quittée)."},
{th:"institutions",q:"Quand célèbre-t-on la journée de l'Europe ?",a:"Le 9 mai",w:["Le 14 juillet","Le 1er janvier","Le 11 novembre"],e:"En souvenir de la déclaration Schuman du 9 mai 1950."},
{th:"institutions",q:"À quelle fréquence les élections européennes sont-elles organisées ?",a:"Tous les 5 ans",w:["Tous les 4 ans","Tous les 6 ans","Tous les 7 ans"],e:"Les dernières ont eu lieu en juin 2024."},
{th:"institutions",q:"Quelle condition est nécessaire pour voter aux élections européennes en France ?",a:"Être citoyen de l'Union européenne, majeur et inscrit sur les listes",w:["Être né en France","Parler trois langues européennes","Avoir vécu dans deux pays de l'UE"],e:"Un citoyen de l'UE résidant en France peut voter aux européennes et aux municipales."},
{th:"institutions",q:"Quel pays est un pays fondateur de l'Union européenne ?",a:"L'Italie",w:["L'Espagne","La Suède","La Pologne"],e:"Les 6 fondateurs (1957) : France, Allemagne, Italie, Belgique, Pays-Bas, Luxembourg."},
{th:"institutions",s:1,q:"Vous serez absent le jour d'une élection. Que pouvez-vous faire pour voter quand même ?",a:"Donner une procuration à un autre électeur",w:["Envoyer un SMS à la mairie","Voter le lendemain","Demander à n'importe qui de voter avec votre carte"],e:"La procuration se fait en ligne (maprocuration.gouv.fr) puis en commissariat, gendarmerie ou consulat."},

// ===================== DROITS ET DEVOIRS =====================
{th:"droits",q:"Au nom de quoi l'État peut-il justifier la restriction de certains droits ?",a:"De l'ordre public et de l'intérêt général",w:["Des intérêts d'un parti politique","Des convictions religieuses du président","Des préférences des voisins"],e:"Une restriction doit être prévue par la loi, nécessaire et proportionnée."},
{th:"droits",q:"Concernant le droit de se marier, quelle proposition est correcte ?",a:"Le mariage exige le libre consentement des deux époux majeurs",w:["La famille peut choisir l'époux","On peut se marier à 14 ans","Un homme peut avoir plusieurs épouses"],e:"Le mariage forcé et la polygamie sont interdits ; le mariage est ouvert aux couples de même sexe depuis 2013."},
{th:"droits",q:"Est-il toujours possible de divorcer ?",a:"Oui, chacun des époux peut demander le divorce",w:["Non, le mariage est définitif","Seulement le mari","Seulement après 20 ans de mariage"],e:"Femme ou homme, chacun peut engager une procédure de divorce."},
{th:"droits",q:"La peine de mort est :",a:"Abolie en France",w:["Appliquée pour les crimes graves","Réservée aux terroristes","Décidée par le président"],e:"Abolie en 1981 (loi Badinter), interdiction inscrite dans la Constitution en 2007."},
{th:"droits",q:"Laquelle de ces citations est inscrite dans la Déclaration des droits de l'homme et du citoyen de 1789 ?",a:"« Les hommes naissent et demeurent libres et égaux en droits »",w:["« Je pense, donc je suis »","« L'État, c'est moi »","« Tous pour un, un pour tous »"],e:"C'est l'article 1er de la Déclaration de 1789."},
{th:"droits",q:"Le recours à l'avortement est-il autorisé ?",a:"Oui, c'est une liberté garantie par la Constitution",w:["Non, il est interdit","Seulement à l'étranger","Seulement avec l'accord du mari"],e:"Légalisé en 1975 (loi Veil), inscrit dans la Constitution en 2024 ; possible jusqu'à 14 semaines de grossesse."},
{th:"droits",q:"Que contient la Constitution ?",a:"L'organisation des pouvoirs publics et les droits fondamentaux",w:["Le code de la route","Les horaires des services publics","La liste des impôts locaux"],e:"Son préambule renvoie à la DDHC de 1789, au préambule de 1946 et à la Charte de l'environnement."},
{th:"droits",q:"Que garantit la liberté de la presse ?",a:"Le droit pour les journalistes d'informer sans censure préalable",w:["Le droit de publier de fausses accusations","Le contrôle des journaux par le gouvernement","L'obligation d'acheter un journal"],e:"Loi du 29 juillet 1881 ; la diffamation reste punie."},
{th:"droits",q:"Que prévoit la Charte de l'environnement ?",a:"Le droit de vivre dans un environnement sain et le devoir de le préserver",w:["L'interdiction des voitures","Le droit de polluer si on paie","La suppression des parcs naturels"],e:"Adossée à la Constitution depuis 2005."},
{th:"droits",q:"Que signifie la dignité humaine ?",a:"Toute personne doit être respectée et ne peut être traitée comme un objet",w:["Certaines personnes valent plus que d'autres","Seuls les citoyens ont des droits","Le respect dépend de la richesse"],e:"Principe à valeur constitutionnelle : interdit la torture, l'esclavage, les traitements dégradants."},
{th:"droits",q:"Que signifie le droit de manifester ?",a:"Pouvoir exprimer collectivement ses opinions sur la voie publique, de façon déclarée et pacifique",w:["Pouvoir casser des biens publics","Pouvoir bloquer les hôpitaux","Pouvoir manifester armé"],e:"Une manifestation doit être déclarée à l'avance en mairie ou en préfecture."},
{th:"droits",q:"Que signifie PMA ?",a:"Procréation médicalement assistée",w:["Prime mensuelle d'activité","Permis de mariage autorisé","Protection maternelle et infantile"],e:"Depuis 2021, la PMA est ouverte aux couples de femmes et aux femmes seules."},
{th:"droits",q:"À quoi la PMA est-elle liée ?",a:"Au droit de fonder une famille et à la liberté de disposer de son corps",w:["À la liberté de la presse","À la liberté d'association","Au droit de grève"],e:"La PMA permet d'avoir un enfant grâce à l'aide médicale."},
{th:"droits",q:"Quel texte est le plus difficile à modifier ?",a:"La Constitution",w:["Un décret","Un arrêté municipal","Une circulaire"],e:"Sa révision exige un vote du Congrès aux 3/5 ou un référendum."},
{th:"droits",q:"Quelle liberté permet à une personne de croire en la religion de son choix ?",a:"La liberté de conscience",w:["La liberté de la presse","La liberté de circulation","La liberté d'entreprendre"],e:"Elle implique aussi le droit de ne pas croire."},
{th:"droits",q:"Qu'est-ce que le droit de grève ?",a:"Le droit de cesser collectivement le travail pour défendre des revendications professionnelles",w:["Le droit de ne plus jamais travailler","Le droit de bloquer l'entreprise par la violence","Le droit de prendre des vacances quand on veut"],e:"Droit constitutionnel (préambule de 1946) ; le salaire n'est pas versé pendant la grève."},
{th:"droits",q:"Qu'est-ce que la Constitution ?",a:"Le texte fondamental qui organise l'État et garantit les libertés",w:["Un livre d'histoire","Le règlement de l'Assemblée","Un traité européen"],e:"Constitution de la Ve République, du 4 octobre 1958."},
{th:"droits",q:"Qui peut demander à avorter ?",a:"Toute femme enceinte qui le souhaite, y compris mineure",w:["Seulement les femmes mariées","Seulement avec l'accord du père","Seulement les femmes françaises"],e:"Une mineure peut garder le secret vis-à-vis de ses parents si elle est accompagnée d'un adulte de son choix."},
{th:"droits",q:"Une femme majeure de nationalité française a-t-elle le droit de voter aux élections ?",a:"Oui, depuis 1944",w:["Non","Seulement aux municipales","Seulement avec l'accord de son mari"],e:"Droit de vote des femmes : ordonnance du 21 avril 1944, premier vote en 1945."},
{th:"droits",q:"Concernant l'utilisation des réseaux sociaux, quelle proposition est correcte ?",a:"La loi s'applique aussi en ligne : insultes et harcèlement sont punis",w:["Tout est permis sur Internet","L'anonymat empêche toute poursuite","On peut publier la photo de n'importe qui sans accord"],e:"Le cyberharcèlement est un délit ; le droit à l'image s'applique aussi."},
{th:"droits",q:"Jeter un mégot par terre est :",a:"Une infraction punie d'une amende",w:["Autorisé","Autorisé la nuit","Autorisé en ville seulement"],e:"Abandon de déchet sur la voie publique : amende forfaitaire de 135 €."},
{th:"droits",q:"L'État peut-il limiter les droits et libertés ?",a:"Oui, dans les cas prévus par la loi, pour protéger l'ordre public ou les droits d'autrui",w:["Non, jamais","Oui, sans aucune justification","Oui, selon l'humeur du gouvernement"],e:"Ex. : confinement sanitaire, état d'urgence, interdiction d'une manifestation dangereuse."},
{th:"droits",q:"Parmi ces actions, laquelle permet d'adopter une attitude respectueuse de l'environnement ?",a:"Trier ses déchets",w:["Laisser les lumières allumées","Jeter ses ordures dans la nature","Laisser couler l'eau"],e:"Le tri permet le recyclage et réduit la pollution."},
{th:"droits",q:"Quelle proposition constitue une obligation ?",a:"Payer ses impôts",w:["Voter","Adhérer à un syndicat","Pratiquer une religion"],e:"Le vote est un droit, pas une obligation légale ; l'impôt, lui, est obligatoire."},
{th:"droits",q:"Pour quel motif peut-on limiter la liberté d'expression ?",a:"Pour sanctionner l'injure, la diffamation ou l'incitation à la haine",w:["Pour interdire de critiquer le gouvernement","Pour interdire l'humour","Pour interdire les opinions minoritaires"],e:"La critique du pouvoir est libre ; les abus prévus par la loi sont punis."},
{th:"droits",q:"Pourquoi doit-on trier ses déchets ?",a:"Pour permettre leur recyclage et protéger l'environnement",w:["Pour payer moins d'impôt sur le revenu","Parce que c'est une tradition religieuse","Pour remplir les décharges plus vite"],e:"Le tri est obligatoire selon les règles de sa commune."},
{th:"droits",q:"Que doit faire une victime de violences ?",a:"Porter plainte auprès de la police ou de la gendarmerie",w:["Se venger elle-même","Garder le silence","Attendre que cela passe"],e:"Numéros utiles : 17 (police), 3919 (violences faites aux femmes), 119 (enfance en danger)."},
{th:"droits",q:"Que doit-on faire face aux ordres des policiers ou des gendarmes ?",a:"Les respecter",w:["Les ignorer","Négocier systématiquement","S'enfuir"],e:"Le refus d'obtempérer est un délit ; on peut ensuite contester un abus devant l'IGPN ou le Défenseur des droits."},
{th:"droits",q:"Quel est le rôle de la police ?",a:"Protéger les personnes et les biens et faire respecter la loi",w:["Juger les délinquants","Voter les lois","Collecter les impôts"],e:"Police en ville, gendarmerie surtout en zone rurale."},
{th:"droits",q:"Quel est un exemple d'assistance à personne en danger ?",a:"Appeler les secours quand quelqu'un fait un malaise dans la rue",w:["Filmer la scène sans intervenir","Passer son chemin","Attendre que quelqu'un d'autre réagisse"],e:"Ne pas porter assistance à une personne en danger est un délit ; appeler le 15, 18 ou 112 suffit souvent."},
{th:"droits",q:"Quel exemple illustre une limitation de liberté pour protéger l'intérêt général ?",a:"La limitation de vitesse sur les routes",w:["Le droit de vote","La liberté de religion","Le droit de se marier"],e:"La liberté de circuler est encadrée pour protéger la sécurité de tous."},
{th:"droits",q:"Quelle est l'attitude à avoir lorsqu'on est témoin de violences ?",a:"Alerter les secours ou la police",w:["Ne rien faire","Prendre une photo pour les réseaux sociaux","Se battre avec l'agresseur"],e:"Le 17 (ou le 112) permet d'alerter sans se mettre en danger."},
{th:"droits",q:"Quelle est l'infraction la plus grave ?",a:"Le crime",w:["Le délit","La contravention","L'incivilité"],e:"Trois catégories : contravention < délit < crime (jugé par la cour d'assises ou la cour criminelle)."},
{th:"droits",q:"Quelle obligation concerne toutes les personnes résidant en France, quelle que soit leur nationalité ?",a:"Respecter les lois françaises",w:["Voter","Faire le service militaire","Parler uniquement français à la maison"],e:"Nul n'est censé ignorer la loi, français ou étranger."},
{th:"droits",q:"Quelle proposition représente un exemple de crime ?",a:"Un meurtre",w:["Un excès de vitesse","Un stationnement interdit","Un vol à l'étalage"],e:"Meurtre, viol, vol à main armée sont des crimes ; le vol simple est un délit."},
{th:"droits",q:"Quelle proposition représente un exemple de délit ?",a:"Un vol",w:["Un meurtre","Un stationnement gênant","Oublier sa carte d'identité"],e:"Les délits sont jugés par le tribunal correctionnel."},
{th:"droits",q:"Qui veille au maintien de l'ordre public ?",a:"La police et la gendarmerie nationales",w:["Les associations de quartier","Les entreprises privées","Les syndicats"],e:"Sous l'autorité du ministre de l'Intérieur et des préfets (et du maire pour la police municipale)."},
{th:"droits",q:"S'agissant des déchets, quelle proposition est correcte ?",a:"Les encombrants se déposent en déchetterie ou lors des collectes prévues",w:["On peut les laisser sur le trottoir à tout moment","On peut les brûler dans son jardin","On peut les jeter dans la rivière"],e:"Le dépôt sauvage est puni d'une amende."},
{th:"droits",s:1,q:"Une personne vous insulte en raison de votre origine. Que pouvez-vous faire ?",a:"Porter plainte : c'est une injure à caractère raciste, punie par la loi",w:["Rien, c'est la liberté d'expression","Répondre par la violence","Seulement en parler à vos voisins"],e:"On peut aussi signaler les faits en ligne sur PHAROS ou saisir le Défenseur des droits."},

// ===================== HISTOIRE, GÉOGRAPHIE, CULTURE =====================
{th:"histoire",q:"Quel était le surnom de Louis XIV ?",a:"Le Roi-Soleil",w:["Le Bien-Aimé","Le Lion","Le Sage"],e:"Il a régné de 1643 à 1715 et fait construire le château de Versailles."},
{th:"histoire",q:"Quel roi de France a été exécuté pendant la Révolution française ?",a:"Louis XVI",w:["Louis XIV","Henri IV","Charles X"],e:"Guillotiné le 21 janvier 1793."},
{th:"histoire",q:"En quelle année Napoléon Ier est-il devenu empereur ?",a:"1804",w:["1789","1815","1848"],e:"Sacré le 2 décembre 1804 à Notre-Dame de Paris."},
{th:"histoire",q:"Lequel de ces personnages a un lien avec la République française ?",a:"Marianne",w:["Astérix","Jeanne la Folle","Le Petit Prince"],e:"Marianne est le visage symbolique de la République."},
{th:"histoire",q:"De quand date l'appel à la Résistance du général de Gaulle ?",a:"Du 18 juin 1940",w:["Du 14 juillet 1789","Du 8 mai 1945","Du 11 novembre 1918"],e:"Lancé depuis Londres sur les ondes de la BBC."},
{th:"histoire",q:"Pourquoi la Shoah est-elle étudiée à l'école ?",a:"Pour transmettre la mémoire du génocide des Juifs et lutter contre l'antisémitisme et le racisme",w:["Parce que c'est un sujet de géographie","Pour apprendre une langue étrangère","Ce n'est pas étudié à l'école"],e:"Environ 6 millions de Juifs d'Europe ont été assassinés par les nazis."},
{th:"histoire",q:"Quel pays a été colonisé par la France ?",a:"L'Algérie",w:["Le Brésil","L'Inde entière","L'Australie"],e:"L'Algérie a été française de 1830 à son indépendance en 1962."},
{th:"histoire",q:"Depuis quand le président de la République est-il élu au suffrage universel direct ?",a:"Depuis la réforme de 1962 (première élection en 1965)",w:["Depuis 1789","Depuis 1945","Depuis 2000"],e:"Réforme adoptée par référendum en 1962 à l'initiative du général de Gaulle."},
{th:"histoire",q:"Quelle est la première étape de la construction européenne en 1951 ?",a:"La Communauté européenne du charbon et de l'acier (CECA)",w:["La création de l'euro","Le Brexit","L'espace Schengen"],e:"Fondée par le traité de Paris, à l'initiative de Robert Schuman et Jean Monnet."},
{th:"histoire",q:"Durant le mandat de quel président la peine de mort a-t-elle été abolie ?",a:"François Mitterrand",w:["Charles de Gaulle","Jacques Chirac","Valéry Giscard d'Estaing"],e:"Loi du 9 octobre 1981, portée par le garde des Sceaux Robert Badinter."},
{th:"histoire",q:"Quel régime politique a été mis en place pendant la Révolution française en 1792 ?",a:"La Première République",w:["L'Empire","La monarchie absolue","La Ve République"],e:"Proclamée le 21-22 septembre 1792."},
{th:"histoire",q:"Qui était une figure de la Résistance française pendant la Seconde Guerre mondiale ?",a:"Jean Moulin",w:["Louis XIV","Victor Hugo","Napoléon III"],e:"Il a unifié les mouvements de la Résistance intérieure ; il repose au Panthéon."},
{th:"histoire",q:"En 1944, qu'est-ce qui a changé pour les femmes ?",a:"Elles ont obtenu le droit de vote",w:["Elles ont obtenu le droit de travailler","Elles ont obtenu le droit de divorcer","Elles ont obtenu le droit de conduire"],e:"Ordonnance du 21 avril 1944 ; premier vote en avril 1945."},
{th:"histoire",q:"Quelle organisation internationale a été créée en 1945 après la Seconde Guerre mondiale ?",a:"L'Organisation des Nations unies (ONU)",w:["L'Union européenne","L'OTAN","La Société des Nations"],e:"Créée pour maintenir la paix et la sécurité internationales ; la France est membre permanent du Conseil de sécurité."},
{th:"histoire",q:"Quelle peine a été supprimée en 1981 ?",a:"La peine de mort",w:["La prison","L'amende","Les travaux d'intérêt général"],e:"La dernière exécution en France date de 1977."},
{th:"histoire",q:"En quelle année l'euro est-il devenu la monnaie utilisée en France ?",a:"2002",w:["1999","1992","1981"],e:"Il a remplacé le franc le 1er janvier 2002."},
{th:"histoire",q:"En quelle année a commencé la Première Guerre mondiale ?",a:"1914",w:["1870","1918","1939"],e:"1914-1918 ; armistice le 11 novembre 1918."},
{th:"histoire",q:"Où a eu lieu le débarquement allié du 6 juin 1944 ?",a:"En Normandie",w:["En Bretagne","À Marseille","À Calais"],e:"Le D-Day ; un second débarquement a eu lieu en Provence le 15 août 1944."},
{th:"histoire",q:"Quel continent a été le plus concerné par la décolonisation française après la Seconde Guerre mondiale ?",a:"L'Afrique",w:["L'Europe","L'Océanie","L'Amérique du Sud"],e:"La plupart des colonies d'Afrique sont devenues indépendantes autour de 1960."},
{th:"histoire",q:"Que fête-t-on le 8 mai ?",a:"La victoire des Alliés en 1945 et la fin de la guerre en Europe",w:["La prise de la Bastille","L'armistice de 1918","La fête du Travail"],e:"Le 11 novembre commémore l'armistice de 1918, le 14 juillet est la fête nationale."},
{th:"histoire",q:"Quelle mer ou quel océan borde la France métropolitaine ?",a:"La mer Méditerranée",w:["La mer Rouge","L'océan Indien","La mer Noire"],e:"La France est bordée par la Méditerranée, l'océan Atlantique, la Manche et la mer du Nord."},
{th:"histoire",q:"Quel pays a une frontière terrestre avec la France métropolitaine ?",a:"L'Espagne",w:["Le Portugal","L'Autriche","Le Royaume-Uni"],e:"Voisins : Belgique, Luxembourg, Allemagne, Suisse, Italie, Monaco, Espagne, Andorre."},
{th:"histoire",q:"Quelle ville française est un port maritime ?",a:"Marseille",w:["Lyon","Strasbourg","Toulouse"],e:"Marseille est le premier port de France ; Le Havre et Dunkerque sont aussi de grands ports."},
{th:"histoire",q:"Quelle mer se situe entre la France et l'Angleterre ?",a:"La Manche",w:["La mer du Nord","La mer Baltique","La mer Méditerranée"],e:"On peut la traverser par le tunnel sous la Manche."},
{th:"histoire",q:"Qu'est-ce que la France d'outre-mer ?",a:"Les territoires français situés hors d'Europe (Guadeloupe, Martinique, Guyane, La Réunion, Mayotte…)",w:["Les anciennes colonies devenues indépendantes","Les pays francophones","Les ambassades de France"],e:"Ils font partie de la République française."},
{th:"histoire",q:"Quelle chaîne de montagnes est située entre la France et l'Espagne ?",a:"Les Pyrénées",w:["Les Alpes","Le Jura","Les Vosges"],e:"Les Alpes séparent la France de l'Italie et de la Suisse."},
{th:"histoire",q:"Quelle île française se trouve dans l'océan Indien ?",a:"La Réunion",w:["La Martinique","La Guadeloupe","La Corse"],e:"Mayotte est aussi dans l'océan Indien ; la Martinique et la Guadeloupe sont dans la mer des Caraïbes."},
{th:"histoire",q:"Quelle est la population approximative de la France en 2025 ?",a:"Environ 68 millions d'habitants",w:["Environ 45 millions","Environ 90 millions","Environ 120 millions"],e:"Selon l'Insee, environ 68,6 millions d'habitants au 1er janvier 2025."},
{th:"histoire",q:"Quel fleuve traverse Paris ?",a:"La Seine",w:["La Loire","Le Rhône","La Garonne"],e:"La Garonne traverse Toulouse et Bordeaux."},
{th:"histoire",q:"Lequel de ces pays partage des frontières terrestres avec la France ?",a:"La Belgique",w:["Les Pays-Bas","Le Danemark","La Hongrie"],e:"La Belgique est voisine au nord."},
{th:"histoire",q:"Quel pays a une frontière avec la France métropolitaine au nord-est ?",a:"L'Allemagne",w:["L'Espagne","L'Italie","Andorre"],e:"Au nord-est : Belgique, Luxembourg, Allemagne (et la Suisse à l'est)."},
{th:"histoire",q:"Où habite la majorité des Français ?",a:"Dans les villes et leurs agglomérations",w:["À la campagne","En montagne","Dans les territoires d'outre-mer"],e:"Plus de 80 % de la population vit dans des zones urbaines."},
{th:"histoire",q:"Quelle région est la plus peuplée ?",a:"L'Île-de-France",w:["La Bretagne","La Corse","La Normandie"],e:"Environ 12 millions d'habitants, soit près d'un Français sur cinq."},
{th:"histoire",q:"Quelle ville française fait partie des 10 plus grandes métropoles du pays ?",a:"Toulouse",w:["Brest","Ajaccio","Colmar"],e:"Paris, Lyon, Marseille, Toulouse, Lille, Bordeaux, Nantes, Nice… figurent parmi les plus grandes."},
{th:"histoire",q:"Parmi ces pays, lequel attire le plus de visiteurs étrangers chaque année ?",a:"La France",w:["Le Canada","Le Brésil","La Suède"],e:"La France est le pays le plus visité au monde (près de 100 millions de visiteurs par an)."},
{th:"histoire",q:"Quand peut-on visiter gratuitement de nombreux lieux culturels en France ?",a:"Lors des Journées européennes du patrimoine",w:["Le jour de son anniversaire","Le 1er avril","Jamais"],e:"Chaque année en septembre ; de nombreux musées nationaux sont aussi gratuits pour les moins de 26 ans (résidents UE)."},
{th:"histoire",q:"Combien de personnes parlent français dans le monde ?",a:"Plus de 300 millions",w:["Environ 70 millions","Environ 1 milliard","Environ 20 millions"],e:"Selon l'Organisation internationale de la Francophonie, environ 320 millions de locuteurs."},
{th:"histoire",q:"Quel est le classement de la langue française parmi les langues les plus parlées dans le monde ?",a:"Dans les 5 premières",w:["1re","Au-delà de la 20e","2e devant l'anglais"],e:"Le français est généralement classé 5e, derrière l'anglais, le mandarin, l'hindi et l'espagnol."},
{th:"histoire",q:"Qui était Marguerite Yourcenar ?",a:"Une écrivaine, première femme élue à l'Académie française",w:["Une reine de France","Une chanteuse","Une résistante fusillée"],e:"Élue en 1980 ; autrice des « Mémoires d'Hadrien »."},
{th:"histoire",q:"Quel peintre est français ?",a:"Claude Monet",w:["Pablo Picasso","Vincent van Gogh","Léonard de Vinci"],e:"Père de l'impressionnisme (« Impression, soleil levant ») ; Picasso était espagnol, Van Gogh néerlandais."},
{th:"histoire",q:"Quel musée est situé à Paris ?",a:"Le musée du Louvre",w:["Le Prado","Le British Museum","Les Offices"],e:"Le musée le plus visité au monde ; il abrite La Joconde."},
{th:"histoire",q:"Qui était Auguste Rodin ?",a:"Un sculpteur",w:["Un président de la République","Un chanteur","Un footballeur"],e:"Auteur du « Penseur » et du « Baiser »."},
{th:"histoire",q:"Quelle cathédrale célèbre a été en partie détruite par un incendie en 2019 ?",a:"Notre-Dame de Paris",w:["La cathédrale de Chartres","La cathédrale de Strasbourg","La basilique du Sacré-Cœur"],e:"Incendie du 15 avril 2019 ; elle a rouvert en décembre 2024."},
{th:"histoire",q:"Qui était une écrivaine française célèbre ?",a:"George Sand",w:["Marie Curie","Édith Piaf","Coco Chanel"],e:"Romancière du XIXe siècle ; Marie Curie était scientifique, Édith Piaf chanteuse."},
{th:"histoire",q:"Qui était un célèbre musicien français ?",a:"Claude Debussy",w:["Wolfgang Amadeus Mozart","Ludwig van Beethoven","Jean-Sébastien Bach"],e:"Compositeur de « Clair de lune » ; Ravel et Berlioz sont aussi français."},
{th:"histoire",q:"Qui était Auguste Renoir ?",a:"Un peintre impressionniste",w:["Un roi de France","Un général","Un écrivain"],e:"Auteur du « Bal du moulin de la Galette »."},
{th:"histoire",q:"Quelle fête est française ?",a:"Le 14 Juillet",w:["Thanksgiving","Le 4 juillet","La Saint-Patrick"],e:"Fête nationale, en souvenir de la prise de la Bastille (1789) et de la fête de la Fédération (1790)."},
{th:"histoire",q:"Que commémore-t-on le 11 novembre ?",a:"L'armistice de 1918, fin de la Première Guerre mondiale",w:["La victoire de 1945","La prise de la Bastille","La naissance de Napoléon"],e:"C'est un jour férié ; on rend hommage à tous les morts pour la France."},

// ===================== VIVRE DANS LA SOCIÉTÉ FRANÇAISE =====================
{th:"societe",q:"Quel mariage est reconnu par l'État ?",a:"Le mariage civil célébré à la mairie",w:["Le mariage religieux seul","Le mariage coutumier","Le mariage par téléphone"],e:"Le mariage civil doit avoir lieu avant toute cérémonie religieuse."},
{th:"societe",q:"Auprès de quelle institution les parents peuvent-ils inscrire leur enfant à l'école publique ?",a:"La mairie",w:["La préfecture","La caisse d'allocations familiales","Le commissariat"],e:"Puis l'admission se fait auprès du directeur de l'école."},
{th:"societe",q:"En cas de divorce, qui exerce l'autorité parentale ?",a:"En principe, les deux parents ensemble",w:["Toujours le père","Toujours la mère","Le juge"],e:"Le divorce ne change pas l'autorité parentale, sauf décision contraire du juge dans l'intérêt de l'enfant."},
{th:"societe",q:"Quelle aide permet aux personnes qui ont des difficultés financières d'avoir un avocat ?",a:"L'aide juridictionnelle",w:["Le RSA","L'APL","La prime d'activité"],e:"L'État prend en charge tout ou partie des frais de justice selon les revenus."},
{th:"societe",q:"Où faut-il déclarer la naissance d'un enfant ?",a:"À la mairie du lieu de naissance",w:["À la préfecture","À l'église","À la banque"],e:"Dans les 5 jours qui suivent l'accouchement."},
{th:"societe",q:"Quelle est l'une des conditions pour passer l'examen du permis de conduire (voiture) ?",a:"Avoir au moins 17 ans",w:["Être propriétaire d'une voiture","Avoir le baccalauréat","Être marié"],e:"Depuis 2024, on peut passer et obtenir le permis B dès 17 ans."},
{th:"societe",q:"Un bail locatif est valide s'il est :",a:"Écrit et signé par le locataire et le propriétaire",w:["Seulement oral","Signé par un voisin","Envoyé par SMS"],e:"Le contrat de location doit être écrit et préciser loyer, durée, dépôt de garantie…"},
{th:"societe",q:"Où peut-on déposer un lave-vaisselle cassé ?",a:"À la déchetterie (ou le faire reprendre par le vendeur)",w:["Sur le trottoir devant chez soi","Dans la poubelle de tri","Dans un parc"],e:"Les magasins doivent reprendre l'ancien appareil lors de l'achat d'un neuf."},
{th:"societe",q:"Quel numéro d'urgence permet d'appeler la police ?",a:"Le 17",w:["Le 15","Le 18","Le 3919"],e:"15 : SAMU · 18 : pompiers · 112 : numéro d'urgence européen · 114 : par SMS."},
{th:"societe",q:"Quel numéro appeler pour une urgence médicale (SAMU) ?",a:"Le 15",w:["Le 17","Le 18","Le 119"],e:"Le 18 pour les pompiers, le 112 fonctionne dans toute l'Europe."},
{th:"societe",q:"Concernant l'accès aux soins, quelle proposition est correcte ?",a:"Toute personne malade ou blessée doit être soignée, notamment aux urgences",w:["Les hôpitaux soignent seulement les Français","Il faut payer avant d'entrer aux urgences","Seuls les salariés peuvent être soignés"],e:"L'hôpital public doit accueillir toute personne en urgence."},
{th:"societe",q:"À qui est accessible la contraception ?",a:"À toute personne qui le souhaite, y compris les mineurs",w:["Uniquement aux femmes mariées","Uniquement avec l'accord des parents","Uniquement après 25 ans"],e:"Elle est gratuite pour les moins de 26 ans."},
{th:"societe",q:"Qu'est-ce que le principe de confidentialité dans le domaine de la santé ?",a:"Le secret médical : le médecin ne peut pas divulguer les informations du patient",w:["Le médecin informe l'employeur","Le médecin publie les dossiers","La famille a accès à tout"],e:"Le secret médical protège la vie privée du patient."},
{th:"societe",q:"L'inscription à l'Assurance maladie est :",a:"Obligatoire",w:["Facultative","Réservée aux Français","Payante pour tous"],e:"Toute personne qui travaille ou réside en France de façon stable et régulière est affiliée."},
{th:"societe",q:"Qui peut demander un congé parental d'éducation ?",a:"La mère ou le père salarié",w:["Uniquement la mère","Uniquement le père","Uniquement les grands-parents"],e:"Ouvert à chacun des parents, sous condition d'ancienneté (1 an dans l'entreprise)."},
{th:"societe",q:"Quelles sont les affaires traitées par le conseil de prud'hommes ?",a:"Les litiges entre salariés et employeurs",w:["Les divorces","Les crimes","Les conflits entre voisins"],e:"Licenciement contesté, salaire impayé, heures supplémentaires…"},
{th:"societe",q:"Travailler sans être déclaré est :",a:"Illégal (travail dissimulé)",w:["Autorisé si on est d'accord","Autorisé le week-end","Autorisé pour les étudiants"],e:"Le travail non déclaré prive de protection sociale (retraite, maladie, chômage)."},
{th:"societe",q:"Lorsqu'un employeur demande à un salarié de travailler plus longtemps que la durée prévue dans le contrat :",a:"Les heures supplémentaires doivent être payées (majorées) ou récupérées",w:["Le salarié n'est pas payé","Le salarié doit payer l'employeur","C'est interdit dans tous les cas"],e:"La durée légale du travail est de 35 heures par semaine."},
{th:"societe",q:"Quelle est la mission de France Travail ?",a:"Aider les demandeurs d'emploi à trouver un travail et les indemniser",w:["Délivrer les passeports","Collecter les impôts","Gérer les écoles"],e:"Anciennement Pôle emploi (renommé en 2024)."},
{th:"societe",q:"Dans une entreprise, le droit syndical permet :",a:"D'adhérer librement à un syndicat pour défendre ses intérêts",w:["D'obliger tous les salariés à se syndiquer","De ne plus venir travailler","De licencier un collègue"],e:"Aucun salarié ne peut être sanctionné pour son appartenance syndicale."},
{th:"societe",q:"Dans une entreprise, le droit de grève autorise :",a:"À arrêter collectivement le travail pour des revendications, sans être licencié pour cela",w:["À casser le matériel","À empêcher les autres de travailler par la force","À être payé pendant la grève"],e:"Les jours de grève ne sont pas payés."},
{th:"societe",q:"Quelles sont les conditions pour toucher les allocations chômage ?",a:"Avoir assez travaillé avant, avoir perdu son emploi involontairement et être inscrit à France Travail",w:["Avoir démissionné sans raison","Avoir plus de 60 ans","Être propriétaire"],e:"Il faut aussi rechercher activement un emploi."},
{th:"societe",q:"Qu'est-ce que l'école maternelle ?",a:"L'école des enfants de 3 à 6 ans",w:["L'école réservée aux mères","Le collège","Une crèche pour bébés"],e:"Elle fait partie de l'instruction obligatoire depuis 2019."},
{th:"societe",q:"Comment s'appelle le diplôme passé par les élèves à la fin du collège ?",a:"Le diplôme national du brevet",w:["Le baccalauréat","Le CAP","La licence"],e:"Le baccalauréat se passe à la fin du lycée."},
{th:"societe",q:"Les parents d'élèves ont le droit de :",a:"Être informés de la scolarité de leur enfant et élire leurs représentants",w:["Choisir les notes de leur enfant","Modifier le programme scolaire","Assister à tous les cours"],e:"Ils peuvent rencontrer les enseignants et voter aux élections des représentants de parents."},
{th:"societe",q:"Qui peut manger à la cantine scolaire ?",a:"Tous les élèves dont les parents le demandent",w:["Seulement les enfants de fonctionnaires","Seulement les enfants français","Seulement les enfants dont les deux parents travaillent"],e:"L'accès ne peut pas être refusé pour discrimination ; les tarifs dépendent souvent des revenus."},
{th:"societe",q:"À quel âge commence l'instruction obligatoire des enfants ?",a:"3 ans",w:["6 ans","2 ans","5 ans"],e:"Obligatoire de 3 à 16 ans, puis obligation de formation jusqu'à 18 ans."},
{th:"societe",q:"Quel est l'âge de la majorité en France ?",a:"18 ans",w:["16 ans","20 ans","21 ans"],e:"À 18 ans, on peut voter et on est pleinement responsable de ses actes."},
{th:"societe",q:"À l'école, il est interdit aux parents de :",a:"Menacer ou insulter les enseignants",w:["Rencontrer les enseignants","Consulter les notes de leur enfant","Participer aux réunions de parents"],e:"Les personnels de l'école sont protégés par la loi."},
{th:"societe",q:"Quel motif d'absence est accepté par l'école ?",a:"La maladie de l'enfant",w:["Des vacances prolongées","Un jour de soldes","Une fête entre amis"],e:"Les absences doivent être justifiées ; trop d'absences injustifiées sont signalées."},
{th:"societe",q:"Quand ont lieu les vacances scolaires de Noël ?",a:"Fin décembre – début janvier, pendant environ deux semaines",w:["En juillet","En février uniquement","Il n'y en a pas"],e:"Le calendrier est fixé par le ministère de l'Éducation nationale."},
{th:"societe",q:"À l'école, un enfant en situation de handicap :",a:"A le droit d'être scolarisé, avec des aménagements si besoin",w:["Ne peut pas aller à l'école","Doit forcément rester chez lui","Doit payer plus cher"],e:"Il peut être accompagné par un AESH (accompagnant d'élèves en situation de handicap)."},
{th:"societe",s:1,q:"Votre propriétaire refuse de vous rendre votre dépôt de garantie sans raison après votre départ. Que pouvez-vous faire ?",a:"Lui envoyer une lettre recommandée, puis saisir la commission de conciliation ou le tribunal",w:["Entrer chez lui pour récupérer l'argent","Rien, il a tous les droits","Casser la porte du logement"],e:"Le dépôt doit être rendu sous 1 mois (état des lieux conforme) ou 2 mois sinon."},
{th:"societe",s:1,q:"Vous êtes malade et ne pouvez pas aller travailler. Que devez-vous faire ?",a:"Consulter un médecin et envoyer l'arrêt de travail à votre employeur et à l'Assurance maladie",w:["Ne rien dire à personne","Démissionner","Envoyer un collègue à votre place"],e:"L'arrêt doit être transmis sous 48 heures."},
{th:"societe",s:1,q:"Vous voyez de la fumée sortir d'un appartement de votre immeuble. Que faites-vous ?",a:"J'appelle le 18 (pompiers) ou le 112",w:["J'attends de voir si ça s'arrête","J'appelle mon propriétaire","Je publie une vidéo sur les réseaux sociaux"],e:"Les pompiers interviennent pour les incendies et les secours aux personnes."},
{th:"societe",s:1,q:"Votre employeur vous demande de travailler sans contrat ni fiche de paie. Que dit la loi ?",a:"C'est du travail dissimulé, interdit et puni",w:["C'est normal pendant la période d'essai","C'est autorisé si le salaire est élevé","C'est autorisé pour les étrangers"],e:"Vous pouvez contacter l'inspection du travail."}
];
